class Compressor:
    """Residual-adaptive stable-support hybrid compressor.

    Uses error feedback, dense transmission for critical 1D statistics,
    EMA-stabilized TopK support, and a low-rank fallback for matrix/conv
    gradients when rank-1 is cheaper and more accurate than sparse updates.
    """

    def __init__(self, compress_ratio=0.01):
        self.compress_ratio = compress_ratio
        self.residuals = {}
        self.scores = {}
        self.subspaces = {}
        self.beta = 0.9
        self.eps = 1e-8
        self.small_tensor = max(128, int(1.0 / max(compress_ratio, 1e-8)))

    def compress(self, tensor, name):
        residual = self.residuals.get(name)
        tensor = tensor if residual is None else tensor + residual
        shape, flat = tensor.shape, tensor.flatten()
        numel = flat.numel()

        if tensor.ndim == 1 or numel <= self.small_tensor:
            self.residuals[name] = torch.zeros_like(tensor)
            return [flat.clone()], ('dense', shape)

        score = self.scores.get(name)
        if score is None or score.numel() != numel or score.device != flat.device:
            score = flat.abs()
        else:
            score = self.beta * score + (1.0 - self.beta) * flat.abs()
        self.scores[name] = score.detach()

        boost = 0.0 if residual is None else min(
            3.0, (residual.norm() / (tensor.norm() + self.eps)).item())
        k = max(1, min(numel, int(numel * self.compress_ratio * (1.0 + boost))))
        _, indices = torch.topk(score, k, sorted=False)
        values = flat[indices]
        sparse = torch.zeros_like(flat)
        sparse.scatter_(0, indices, values)
        sparse_rec = sparse.view(shape)
        sparse_err = (tensor - sparse_rec).norm()

        if tensor.ndim in (2, 4):
            mat = tensor.reshape(tensor.shape[0], -1)
            m, n = mat.shape
            if min(m, n) > 1 and (m + n + 1) <= 2 * k:
                q = self.subspaces.get(name)
                if q is None or q.numel() != n or q.device != mat.device:
                    q = torch.randn(n, device=mat.device, dtype=mat.dtype)
                q = q / (q.norm() + self.eps)
                p = mat.mv(q)
                p = p / (p.norm() + self.eps)
                q = mat.t().mv(p)
                q = q / (q.norm() + self.eps)
                self.subspaces[name] = q.detach()
                sigma = p.dot(mat.mv(q))
                low_rank = (sigma * torch.outer(p, q)).view(shape)
                if (tensor - low_rank).norm() <= sparse_err:
                    self.residuals[name] = (tensor - low_rank).detach()
                    return [p, q, sigma.view(1)], ('lowrank', shape)

        self.residuals[name] = (tensor - sparse_rec).detach()
        return [values, indices], ('topk', numel, shape)

    def decompress(self, compressed_tensors, ctx):
        if ctx[0] == 'dense':
            return compressed_tensors[0].view(ctx[1])
        if ctx[0] == 'topk':
            _, numel, shape = ctx
            values, indices = compressed_tensors
            out = torch.zeros(numel, dtype=values.dtype, device=values.device)
            out.scatter_(0, indices, values)
            return out.view(shape)
        p, q, sigma = compressed_tensors
        return (sigma * torch.outer(p, q)).view(ctx[1])
